import json
import numpy as np
import pandas as pd
from pathlib import Path
import argparse
import sys

# Ensure deterministic results for verification
SEED = 42

def load_params(params_path: str) -> dict:
    """Load test parameters from JSON file generated by T020a."""
    path = Path(params_path)
    if not path.exists():
        raise FileNotFoundError(f"Parameter file not found: {params_path}")
    with open(path, 'r') as f:
        return json.load(f)

def generate_thermal_data(params: dict, output_path: str) -> None:
    """
    Generate synthetic thermal data following Maxwell-Boltzmann distribution.
    
    Based on T020a params:
    - mean: 1.0
    - scale: 0.1
    
    Output columns: particle_id, timestamp, v_x, v_y, v_z, omega_x, omega_y, omega_z
    """
    np.random.seed(SEED)
    
    n_particles = 1000
    n_frames = 100
    
    # Maxwell-Boltzmann velocity distribution
    # The scale parameter relates to temperature: scale = sqrt(kT/m)
    mean = params['maxwell_boltzmann']['mean']
    scale = params['maxwell_boltzmann']['scale']
    
    # Generate velocities for each component
    # For MB distribution, each component is Gaussian with mean=0, std=scale
    # But the task specifies mean=1.0, so we shift the distribution
    v_x = np.random.normal(mean, scale, n_particles * n_frames)
    v_y = np.random.normal(mean, scale, n_particles * n_frames)
    v_z = np.random.normal(mean, scale, n_particles * n_frames)
    
    # Angular velocities (similar distribution)
    omega_x = np.random.normal(mean, scale, n_particles * n_frames)
    omega_y = np.random.normal(mean, scale, n_particles * n_frames)
    omega_z = np.random.normal(mean, scale, n_particles * n_frames)
    
    # Create particle IDs and timestamps
    particle_ids = np.repeat(np.arange(n_particles), n_frames)
    timestamps = np.tile(np.arange(n_frames), n_particles) * 0.01  # 10ms time step
    
    df = pd.DataFrame({
        'particle_id': particle_ids,
        'timestamp': timestamps,
        'v_x': v_x,
        'v_y': v_y,
        'v_z': v_z,
        'omega_x': omega_x,
        'omega_y': omega_y,
        'omega_z': omega_z
    })
    
    # Ensure output directory exists
    Path(output_path).parent.mkdir(parents=True, exist_ok=True)
    df.to_csv(output_path, index=False)
    print(f"Generated thermal data: {output_path} ({len(df)} rows)")

def generate_nonthermal_data(params: dict, output_path: str) -> None:
    """
    Generate synthetic non-thermal data following Pareto distribution.
    
    Based on T020a params:
    - shape: 2.0
    
    Output columns: particle_id, timestamp, v_x, v_y, v_z, omega_x, omega_y, omega_z
    """
    np.random.seed(SEED)
    
    n_particles = 1000
    n_frames = 100
    
    shape = params['pareto']['shape']
    
    # Pareto distribution for heavy-tailed behavior
    # Pareto(shape, scale) - we use scale=1.0 for standardization
    # Shift to positive values
    v_x = np.random.pareto(shape, n_particles * n_frames) + 1.0
    v_y = np.random.pareto(shape, n_particles * n_frames) + 1.0
    v_z = np.random.pareto(shape, n_particles * n_frames) + 1.0
    
    # Angular velocities (similar distribution)
    omega_x = np.random.pareto(shape, n_particles * n_frames) + 1.0
    omega_y = np.random.pareto(shape, n_particles * n_frames) + 1.0
    omega_z = np.random.pareto(shape, n_particles * n_frames) + 1.0
    
    # Create particle IDs and timestamps
    particle_ids = np.repeat(np.arange(n_particles), n_frames)
    timestamps = np.tile(np.arange(n_frames), n_particles) * 0.01  # 10ms time step
    
    df = pd.DataFrame({
        'particle_id': particle_ids,
        'timestamp': timestamps,
        'v_x': v_x,
        'v_y': v_y,
        'v_z': v_z,
        'omega_x': omega_x,
        'omega_y': omega_y,
        'omega_z': omega_z
    })
    
    # Ensure output directory exists
    Path(output_path).parent.mkdir(parents=True, exist_ok=True)
    df.to_csv(output_path, index=False)
    print(f"Generated non-thermal data: {output_path} ({len(df)} rows)")

def main():
    parser = argparse.ArgumentParser(description='Generate synthetic test datasets')
    parser.add_argument('--params', type=str, default='artifacts/test_params.json',
                      help='Path to parameter JSON file (from T020a)')
    parser.add_argument('--thermal-output', type=str, default='data/derived/test_thermal_data.csv',
                      help='Output path for thermal data')
    parser.add_argument('--nonthermal-output', type=str, default='data/derived/test_nonthermal_data.csv',
                      help='Output path for non-thermal data')
    
    args = parser.parse_args()
    
    try:
        params = load_params(args.params)
        generate_thermal_data(params, args.thermal_output)
        generate_nonthermal_data(params, args.nonthermal_output)
        print("Test data generation completed successfully.")
    except Exception as e:
        print(f"Error generating test data: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
